import{_ as a,o as e,c as l,a2 as o}from"./chunks/framework.Crpw6aS5.js";const d=JSON.parse('{"title":"科尔曼·莫格勒","description":"","frontmatter":{"title":"科尔曼·莫格勒","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/科尔曼·莫格勒.md","filePath":"04_people/科尔曼·莫格勒.md"}'),r={name:"04_people/科尔曼·莫格勒.md"};function i(n,t,s,_,u,h){return e(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="科尔曼·莫格勒" tabindex="-1">科尔曼·莫格勒 <a class="header-anchor" href="#科尔曼·莫格勒" aria-label="Permalink to &quot;科尔曼·莫格勒&quot;">​</a></h1><ul><li><strong>角色职位</strong>：吉列（Gillette）公司董事长</li><li><strong>与巴菲特关系</strong>：吉列董事会成员，巴菲特投资吉列的重要联系人</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>科尔曼·莫格勒是吉列公司的董事长，同时也是吉列董事会的重要成员。吉列是巴菲特投资生涯中最成功的案例之一，其&quot;刀片+刀架&quot;的商业模式与伯克希尔的投资理念高度契合。莫格勒作为董事长，在吉列的战略发展和公司治理中扮演着核心角色。</p><p>在莫格勒的领导下，吉列持续推进产品创新和市场扩张。公司旗下的吉列剃须刀系列长期占据全球市场主导地位，新收购的Duracell金霸王电池业务也进一步丰富了产品组合。莫格勒在平衡短期盈利与长期品牌建设方面展现出了卓越的管理智慧。</p><p>巴菲特对吉列的投资始于1989年，此后一直持有至2005年宝洁收购吉列为止，是伯克希尔持仓时间最长的股票之一。巴菲特曾多次表达对吉列管理层的赞赏，称其为&quot;世界上最好的管理层之一&quot;。莫格勒治下的吉列董事会运作高效、决策透明，为伯克希尔这笔长期投资提供了可靠的公司治理保障。这段投资关系充分体现了巴菲特&quot;找到优秀公司、优秀管理层、长期持有&quot;的核心投资哲学。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1989年</strong>：巴菲特首次投资吉列，莫格勒时任董事会成员</li><li><strong>1990-2000年代</strong>：担任吉列董事长，持续为股东创造价值</li><li><strong>2005年</strong>：宝洁收购吉列，伯克希尔持有吉列长达16年的投资画上句号</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=科尔曼·莫格勒在1990年股东信中的原话">1990年：完整翻译|/01_letters/1990年/翻译</a></li></ul>',11)])])}const c=a(r,[["render",i]]);export{d as __pageData,c as default};
